import React from 'react';import{createRoot}from'react-dom/client';import{MyDocuments}from'../../src/MyDocuments';import{ContractCatalog}from'../../src/ContractCatalog';import{TemplateAdmin}from'../../src/TemplateAdmin';import'../../src/styles.css';import'../../src/enhancements.css';
const mode=new URLSearchParams(location.search).get('mode');const draft={id:'draft-1',kind:'template',title:'Тестовый договор',template_name:'Тестовый договор',created_at:new Date().toISOString(),updated_at:new Date().toISOString(),status:'DRAFT',generated:null};let rows=[draft];let template={id:'template-1',name:'Шаблон для архива',category:'Договоры',status:'ACTIVE',version_count:0};const calls:string[]=[];(window as any).calls=calls;
const api=async(path:string,options:any={})=>{calls.push(`${options.method||'GET'} ${path}`);if(path==='/contract-drafts')return rows;if(path==='/contract-product-drafts')return mode==='legacy'?[{id:'legacy-1',title:'Исторический договор',product_name:'Старый продукт',created_at:new Date().toISOString(),updated_at:new Date().toISOString(),status:'GENERATED',generated:'generated-1'}]:[];if(path==='/contract-product-catalog')return[{id:'legacy-product',name:'Старый продукт',category:'Договоры',description:'Скрытый механизм'}];if(path==='/contract-catalog'||path==='/contract-products')return [];if(path==='/document-templates')return [template];if(path==='/contract-drafts/draft-1'&&options.method==='DELETE'){rows=[];return{ok:true}}if(path==='/contract-drafts/draft-1')return{id:'draft-1',title:'Тестовый договор',template:{name:'Тестовый договор',category:'Договоры'},schema:{fields:[{id:'field-1',field_key:'name',label:'Имя',field_type:'TEXT',position:1,required:false,config:{group:'Сведения'}}],repeating_groups:[]},answers:{}};if(path==='/document-templates/template-1/versions')return [];if(path==='/document-templates/template-1/archive'&&options.method==='POST'){template={...template,status:'ARCHIVED'};return template}if(path==='/document-templates/template-1/restore'&&options.method==='POST'){template={...template,status:'ACTIVE'};return template}throw Error('Unexpected '+path)};
createRoot(document.getElementById('root')!).render((mode==='documents'||mode==='legacy')?<MyDocuments api={api} go={()=>{}}/>:mode==='catalog'?<ContractCatalog api={api} go={()=>{}}/>:<TemplateAdmin api={api}/>);
